script:
frappe.ui.form.on("Order Confirmation", {
    refresh(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button("Send Whatsapp Msg", function () {
                frappe.call({
                    method: "erpnext_order_automation.erpnext_order_app.doctype.order_confirmation.order_confirmation.resend_order_confirmation_whatsapp",
                    args: {
                        order_confirmation: frm.doc.name
                    },
                    freeze: true,
                    freeze_message: "Sending WhatsApp message...",
                    callback: function (r) {
                        if (r.message && r.message.status === "success") {
                            frappe.msgprint("WhatsApp message sent successfully");
                            frm.reload_doc();
                        } else {
                            frappe.msgprint({
                                title: "Failed",
                                message: (r.message && r.message.message) || "Unable to send WhatsApp message",
                                indicator: "red"
                            });
                        }
                    }
                });
            });
        }
    }
});

frappe.ui.form.on("Order Confirmation", {
    setup(frm) {
        frm.set_query("contact_person", function () {
            if (!frm.doc.customer) {
                return {
                    filters: {
                        name: ["=", ""]
                    }
                };
            }

            return {
                query: "frappe.contacts.doctype.contact.contact.contact_query",
                filters: {
                    link_doctype: "Customer",
                    link_name: frm.doc.customer
                }
            };
        });
    },

    customer(frm) {
        frm.set_value("contact_person", "");
    }
});
